    // Base field size
    uint256 constant q   = 21888242871839275222246405745257275088696311157297823662689037894645226208583;

    // Verification Key data
    uint256 constant alphax  = 12865174860305789758458852831237205335997675619707884496772425863580238383580;
    uint256 constant alphay  = 12063642269148894112855732247728940838820030750406622853327372693157429367511;
    uint256 constant betax1  = 11861366198874809853814711447208283536233350311000462709176759189226299720926;
    uint256 constant betax2  = 19637793770556393572958308593025049621625446446911819634341182534513149169204;
    uint256 constant betay1  = 1314921431014847849081775254717937495165393044492098387566279405337426213286;
    uint256 constant betay2  = 15476061440871989085005250801518492638444218407100811726157404809359708448994;
    uint256 constant gammax1 = 11559732032986387107991004021392285783925812861821192530917403151452391805634;
    uint256 constant gammax2 = 10857046999023057135944570762232829481370756359578518086990519993285655852781;
    uint256 constant gammay1 = 4082367875863433681332203403145435568316851327593401208105741076214120093531;
    uint256 constant gammay2 = 8495653923123431417604973247489272438418190587263600148770280649306958101930;
    uint256 constant deltax1 = 9811791045250510572132135899145165994765464057437904543498506725606848035089;
    uint256 constant deltax2 = 8770809331770698524504385187626115848775167167443671833611313281593393098587;
    uint256 constant deltay1 = 8784524342725107050498800726635174285563544417202796221620434532907625785077;
    uint256 constant deltay2 = 7886577022432879973366613225831396060227200594749203638551324952759056045257;


    uint256 constant IC0x = 5263482904685265816057284290751467352069782606144900738540878820687016051554;
    uint256 constant IC0y = 10247548061880689899165280764852856765499943205423947626054468478262057775832;

    uint256 constant IC1x = 4493828080904311448358720435793613410976542645609927418791937757851524776925;
    uint256 constant IC1y = 9475321185967489897707417595222996128976526682389994687946336352962921468506;

    uint256 constant IC2x = 9839343486872750033603084899066758608428621204043398511752064708509667884580;
    uint256 constant IC2y = 18945729695845140201251609246685786927760925419438985779996151116981000200890;

    uint256 constant IC3x = 8418454127112407594369258195922920743506102555978914734155587509331179295934;
    uint256 constant IC3y = 8423691544280455178063262353602936481040403030792903342858000031799108232954;


    // Memory data
    uint16 constant pVk = 0;
    uint16 constant pPairing = 128;

    uint16 constant pLastMem = 896;

    function verifyProof(uint[2] calldata _pA, uint[2][2] calldata _pB, uint[2] calldata _pC, uint[3] calldata _pubSignals) public view returns (bool) {
        assembly {
            function checkField(v) {
                if iszero(lt(v, r)) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            // G1 function to multiply a G1 value(x,y) to value in an address
            function g1_mulAccC(pR, x, y, s) {
                let success
                let mIn := mload(0x40)
                mstore(mIn, x)
                mstore(add(mIn, 32), y)
                mstore(add(mIn, 64), s)

                success := staticcall(sub(gas(), 2000), 7, mIn, 96, mIn, 64)

                if iszero(success) {
                    mstore(0, 0)
                    return(0, 0x20)
                }

                mstore(add(mIn, 64), mload(pR))
                mstore(add(mIn, 96), mload(add(pR, 32)))

                success := staticcall(sub(gas(), 2000), 6, mIn, 128, pR, 64)

                if iszero(success) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            function checkPairing(pA, pB, pC, pubSignals, pMem) -> isOk {
                let _pPairing := add(pMem, pPairing)
                let _pVk := add(pMem, pVk)

                mstore(_pVk, IC0x)
                mstore(add(_pVk, 32), IC0y)

                // Compute the linear combination vk_x

                g1_mulAccC(_pVk, IC1x, IC1y, calldataload(add(pubSignals, 0)))

                g1_mulAccC(_pVk, IC2x, IC2y, calldataload(add(pubSignals, 32)))

                g1_mulAccC(_pVk, IC3x, IC3y, calldataload(add(pubSignals, 64)))


                // -A
                mstore(_pPairing, calldataload(pA))
                mstore(add(_pPairing, 32), mod(sub(q, calldataload(add(pA, 32))), q))

                // B
                mstore(add(_pPairing, 64), calldataload(pB))
                mstore(add(_pPairing, 96), calldataload(add(pB, 32)))
                mstore(add(_pPairing, 128), calldataload(add(pB, 64)))
                mstore(add(_pPairing, 160), calldataload(add(pB, 96)))

                // alpha1
                mstore(add(_pPairing, 192), alphax)
                mstore(add(_pPairing, 224), alphay)

                // beta2
                mstore(add(_pPairing, 256), betax1)
                mstore(add(_pPairing, 288), betax2)
                mstore(add(_pPairing, 320), betay1)
                mstore(add(_pPairing, 352), betay2)

                // vk_x
                mstore(add(_pPairing, 384), mload(add(pMem, pVk)))
                mstore(add(_pPairing, 416), mload(add(pMem, add(pVk, 32))))


                // gamma2
                mstore(add(_pPairing, 448), gammax1)
                mstore(add(_pPairing, 480), gammax2)
                mstore(add(_pPairing, 512), gammay1)
                mstore(add(_pPairing, 544), gammay2)

                // C
                mstore(add(_pPairing, 576), calldataload(pC))
                mstore(add(_pPairing, 608), calldataload(add(pC, 32)))

                // delta2
                mstore(add(_pPairing, 640), deltax1)
                mstore(add(_pPairing, 672), deltax2)
                mstore(add(_pPairing, 704), deltay1)
                mstore(add(_pPairing, 736), deltay2)


                let success := staticcall(sub(gas(), 2000), 8, _pPairing, 768, _pPairing, 0x20)

                isOk := and(success, mload(_pPairing))
            }

            let pMem := mload(0x40)
            mstore(0x40, add(pMem, pLastMem))

            // Validate that all evaluations ∈ F

            checkField(calldataload(add(_pubSignals, 0)))

            checkField(calldataload(add(_pubSignals, 32)))

            checkField(calldataload(add(_pubSignals, 64)))


            // Validate all evaluations
            let isValid := checkPairing(_pA, _pB, _pC, _pubSignals, pMem)

            mstore(0, isValid)
             return(0, 0x20)
         }
     }
 }

contracts/ZKProvenanceTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./ModelAccessControl.sol";
import "./Verifier.sol";

interface IZKModelRegistry {
    function getModelOwner(uint256 _id) external view returns (address);
    function getModelStatus(uint256 _id) external view returns (uint8);
    function isModelStaked(uint256 _id) external view returns (bool);
}

/// @title ZKProvenanceTracker
/// @notice Verifier-gated provenance tracker that preserves the original read model.
contract ZKProvenanceTracker {
    enum EventType {
        REGISTERED,
        ACTIVATED,
        UPDATED,
        DEPRECATED,
        REVOKED,
        VERSION_RELEASED,
        TRANSFERRED,
        STAKED,
        UNSTAKED,
        SLASHED,
        ZK_PROOF_VERIFIED
    }

    struct ProvenanceRecord {
        uint256 recordId;
        uint256 modelId;
        EventType eventType;
        string ipfsMetadata;
        uint256 timestamp;
        address operator;
        bytes32 previousHash;
        bytes32 recordHash;
    }

    uint256 internal constant SNARK_SCALAR_FIELD =
        21888242871839275222246405745257275088548364400416034343698204186575808495617;

    ModelAccessControl public accessControl;
    IZKModelRegistry public registry;
    Groth16Verifier public verifier;

    uint256 private _recordCounter;
    mapping(uint256 => ProvenanceRecord) public records;
    mapping(uint256 => uint256[]) public modelHistory;
    mapping(uint256 => bytes32) public modelChainHead;
    mapping(uint256 => bool) public modelBlacklist;
    mapping(uint256 => string) public blacklistReasons;
    mapping(uint256 => bool) public nullifierUsed;

    event RecordAdded(
        uint256 indexed recordId,
        uint256 indexed modelId,
        EventType indexed eventType,
        address operator
    );
    event ProofVerified(
        uint256 indexed modelId,
        address indexed operator,
        uint256 indexed nullifier,
        uint256 statementHash,
        uint256 timestamp
    );
    event ModelBlacklisted(uint256 indexed modelId, string reason, address by);
    event ModelUnblacklisted(uint256 indexed modelId, address by);

    error ModelIsBlacklisted();
    error NotAuthorized();
    error ModelNotRegistered();
    error InvalidProof();
    error InvalidModelSignal();
    error InvalidStatementHash();
    error NullifierAlreadyUsed();

    constructor(address _accessControl, address _registry, address _verifier) {
        require(_accessControl != address(0), "Tracker: access control required");
        require(_registry != address(0), "Tracker: registry required");
        require(_verifier != address(0), "Tracker: verifier required");
        accessControl = ModelAccessControl(_accessControl);
        registry = IZKModelRegistry(_registry);
        verifier = Groth16Verifier(_verifier);
    }

    function addVerifiedRecord(
        uint256 _modelId,
        EventType _eventType,
        string calldata _canonicalMetadata,
        uint[2] calldata _pA,
        uint[2][2] calldata _pB,
        uint[2] calldata _pC,
        uint[3] calldata _pubSignals
    ) external notBlacklisted returns (uint256) {
        require(
            accessControl.hasRole(accessControl.REGISTRAR(), msg.sender),
            "Tracker: requires REGISTRAR role"
        );

        _checkModelStatus(_modelId);
        if (modelBlacklist[_modelId]) revert ModelIsBlacklisted();

        if (_pubSignals[1] != _modelId) revert InvalidModelSignal();

        uint256 statementHash = _statementHash(_canonicalMetadata);
        if (_pubSignals[2] != statementHash) revert InvalidStatementHash();

        uint256 nullifier = _pubSignals[0];
        if (nullifierUsed[nullifier]) revert NullifierAlreadyUsed();

        bool verified = verifier.verifyProof(_pA, _pB, _pC, _pubSignals);
        if (!verified) revert InvalidProof();

        nullifierUsed[nullifier] = true;
        emit ProofVerified(_modelId, msg.sender, nullifier, statementHash, block.timestamp);

        return _appendRecord(_modelId, _eventType, msg.sender, _canonicalMetadata);
    }

    function blacklistModel(uint256 _modelId, string calldata _reason) external onlyAdmin {
        require(_modelId > 0, "Tracker: invalid model id");
        modelBlacklist[_modelId] = true;
        blacklistReasons[_modelId] = _reason;
        _appendRecord(_modelId, EventType.REVOKED, msg.sender, _reason);
        emit ModelBlacklisted(_modelId, _reason, msg.sender);
    }

    function unblacklistModel(uint256 _modelId) external onlyAdmin {
        require(modelBlacklist[_modelId], "Tracker: not blacklisted");
        modelBlacklist[_modelId] = false;
        delete blacklistReasons[_modelId];
        emit ModelUnblacklisted(_modelId, msg.sender);
    }

    function getModelHistory(uint256 _modelId) external view returns (ProvenanceRecord[] memory) {
        uint256[] storage ids = modelHistory[_modelId];
        ProvenanceRecord[] memory result = new ProvenanceRecord[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = records[ids[i]];
        }
        return result;
    }

    function verifyChain(uint256 _modelId) external view returns (bool) {
        uint256[] storage ids = modelHistory[_modelId];
        if (ids.length == 0) return true;

        bytes32 prevRecordHash = bytes32(0);

        for (uint256 i = 0; i < ids.length; i++) {
            ProvenanceRecord storage record = records[ids[i]];

            if (record.previousHash != prevRecordHash) {
                return false;
            }

            bytes32 computed = keccak256(
                abi.encode(
                    record.recordId,
                    record.modelId,
                    record.eventType,
                    record.ipfsMetadata,
                    record.timestamp,
                    record.operator,
                    record.previousHash
                )
            );
            if (record.recordHash != computed) {
                return false;
            }

            prevRecordHash = record.recordHash;
        }

        return true;
    }

    function getModelsStatus(uint256[] calldata _modelIds)
        external
        view
        returns (uint8[] memory statuses, bool[] memory blacklisted)
    {
        statuses = new uint8[](_modelIds.length);
        blacklisted = new bool[](_modelIds.length);
        for (uint256 i = 0; i < _modelIds.length; i++) {
            statuses[i] = registry.getModelStatus(_modelIds[i]);
            blacklisted[i] = modelBlacklist[_modelIds[i]];
        }
    }

    function computeStatementHash(string calldata _canonicalMetadata) external pure returns (uint256) {
        return _statementHash(_canonicalMetadata);
    }

    function _appendRecord(
        uint256 _modelId,
        EventType _eventType,
        address _operator,
        string memory _ipfsMetadata
    ) internal returns (uint256) {
        uint256 recordId = ++_recordCounter;
        bytes32 prevHash = modelChainHead[_modelId];

        ProvenanceRecord memory record = ProvenanceRecord({
            recordId: recordId,
            modelId: _modelId,
            eventType: _eventType,
            ipfsMetadata: _ipfsMetadata,
            timestamp: block.timestamp,
            operator: _operator,
            previousHash: prevHash,
            recordHash: bytes32(0)
        });

        record.recordHash = keccak256(
            abi.encode(
                record.recordId,
                record.modelId,
                record.eventType,
                record.ipfsMetadata,
                record.timestamp,
                record.operator,
                record.previousHash
            )
        );

        records[recordId] = record;
        modelHistory[_modelId].push(recordId);
        modelChainHead[_modelId] = record.recordHash;

        emit RecordAdded(recordId, _modelId, _eventType, _operator);
        return recordId;
    }

    function _checkModelStatus(uint256 _modelId) internal view {
        if (registry.getModelOwner(_modelId) == address(0)) revert ModelNotRegistered();
        uint8 status = registry.getModelStatus(_modelId);
        require(status != 3, "Tracker: model is revoked");
    }

    function _statementHash(string memory _canonicalMetadata) internal pure returns (uint256) {
        return uint256(keccak256(bytes(_canonicalMetadata))) % SNARK_SCALAR_FIELD;
    }

    modifier notBlacklisted() {
        if (accessControl.isBlacklisted(msg.sender)) revert NotAuthorized();
        _;
    }

    modifier onlyAdmin() {
        if (!accessControl.hasRole(accessControl.ADMIN(), msg.sender)) revert NotAuthorized();
        _;
    }
}

contracts/SignatureGatedProvenanceTracke.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface ISignatureModelRegistry {
    function getModelOwner(uint256 _id) external view returns (address);
}

/**
 * @title SignatureGatedProvenanceTracker
 * @notice Signature-gated variant of the verifier-gated write path.
 *
 *  The admission gate is an EIP-712 typed-data signature produced by the
 *  publisher instead of a Groth16 proof. It serves two purposes:
 *
 *   (1) Lower-cost comparator for the gating primitive (editor comment 2).
 *   (2) User-generated authorisation, so the on-chain owner is the recovered
 *       signer rather than a value asserted by the relay (editor comment 5).
 *
 *  The record layout, hash-linked chaining and statement-hash derivation are
 *  IDENTICAL to ZKProvenanceTracker so that gas figures are comparable.
 */
contract SignatureGatedProvenanceTracker is EIP712 {
    using ECDSA for bytes32;

    // Keep numeric event codes aligned with ZKProvenanceTracker so the
    // three-way experiment uses the same lifecycle state progression.
    enum EventType {
        REGISTERED,
        ACTIVATED,
        UPDATED,
        DEPRECATED,
        REVOKED,
        VERSION_RELEASED,
        TRANSFERRED,
        STAKED,
        UNSTAKED,
        SLASHED,
        ZK_PROOF_VERIFIED
    }

    struct ProvenanceRecord {
        uint256 recordId;
        uint256 modelId;
        EventType eventType;
        string ipfsMetadata;
        uint256 timestamp;
        address operator;
        bytes32 previousHash;
        bytes32 recordHash;
    }

    uint256 internal constant SNARK_SCALAR_FIELD =
        21888242871839275222246405745257275088548364400416034343698204186575808495617;

    // ProvenanceSubmission binds the model, the statement derived from the
    // canonical metadata, the event type, and a one-time nonce. The nonce plays
    // the role the nullifier plays in the proof-gated path.
    bytes32 private constant SUBMISSION_TYPEHASH = keccak256(
        "ProvenanceSubmission(uint256 modelId,uint8 eventType,uint256 statementHash,uint256 nonce)"
    );

    uint256 private _recordCounter;

    mapping(uint256 => ProvenanceRecord) public records;
    mapping(uint256 => uint256[]) public modelHistory;
    mapping(uint256 => bytes32) public modelChainHead;
    mapping(uint256 => bool) public modelBlacklist;
    mapping(uint256 => bool) public nonceUsed;

    ISignatureModelRegistry public immutable registry;

    event RecordAdded(uint256 indexed recordId, uint256 indexed modelId, EventType eventType, address indexed operator);
    event SubmissionAuthorised(uint256 indexed modelId, address indexed signer, uint256 nonce, uint256 statementHash);

    error ModelIsBlacklisted();
    error NonceAlreadyUsed();
    error UnauthorisedSigner();
    error ModelNotRegistered();

    constructor(address _registry) EIP712("ModelProvenance", "1") {
        require(_registry != address(0), "registry required");
        registry = ISignatureModelRegistry(_registry);
    }

    /**
     * @notice Admit a provenance record only if accompanied by a valid
     *         publisher signature over this exact submission.
     * @dev The relay may submit the transaction, but the recorded operator is
     *      the recovered signer, so a compromised relay cannot mis-assign it.
     */
    function addSignedRecord(
        uint256 _modelId,
        EventType _eventType,
        string calldata _canonicalMetadata,
        uint256 _nonce,
        bytes calldata _signature
    ) external returns (uint256) {
        if (modelBlacklist[_modelId]) revert ModelIsBlacklisted();

        address publisher = registry.getModelOwner(_modelId);
        if (publisher == address(0)) revert ModelNotRegistered();

        // Statement hash recomputed on-chain from the metadata being stored.
        uint256 statementHash = _statementHash(_canonicalMetadata);

        if (nonceUsed[_nonce]) revert NonceAlreadyUsed();

        bytes32 digest = _hashTypedDataV4(
            keccak256(abi.encode(SUBMISSION_TYPEHASH, _modelId, uint8(_eventType), statementHash, _nonce))
        );
        address signer = digest.recover(_signature);
        if (signer != publisher) revert UnauthorisedSigner();

        nonceUsed[_nonce] = true;
        emit SubmissionAuthorised(_modelId, signer, _nonce, statementHash);

        // Operator is the authenticated signer, NOT msg.sender (the relay).
        return _appendRecord(_modelId, _eventType, signer, _canonicalMetadata);
    }

    function _appendRecord(
        uint256 _modelId,
        EventType _eventType,
        address _operator,
        string memory _ipfsMetadata
    ) internal returns (uint256) {
        uint256 recordId = ++_recordCounter;
        bytes32 prevHash = modelChainHead[_modelId];

        ProvenanceRecord memory record = ProvenanceRecord({
            recordId: recordId,
            modelId: _modelId,
            eventType: _eventType,
            ipfsMetadata: _ipfsMetadata,
            timestamp: block.timestamp,
            operator: _operator,
            previousHash: prevHash,
            recordHash: bytes32(0)
        });

        record.recordHash = keccak256(
            abi.encode(
                record.recordId, record.modelId, record.eventType, record.ipfsMetadata,
                record.timestamp, record.operator, record.previousHash
            )
        );

        records[recordId] = record;
        modelHistory[_modelId].push(recordId);
        modelChainHead[_modelId] = record.recordHash;

        emit RecordAdded(recordId, _modelId, _eventType, _operator);
        return recordId;
    }

    function _statementHash(string memory _canonicalMetadata) internal pure returns (uint256) {
        return uint256(keccak256(bytes(_canonicalMetadata))) % SNARK_SCALAR_FIELD;
    }

    function statementHashOf(string calldata _canonicalMetadata) external pure returns (uint256) {
        return _statementHash(_canonicalMetadata);
    }

    function getHistoryLength(uint256 _modelId) external view returns (uint256) {
        return modelHistory[_modelId].length;
    }

    function verifyChain(uint256 _modelId) external view returns (bool) {
        uint256[] storage hist = modelHistory[_modelId];
        bytes32 prev = bytes32(0);
        for (uint256 i = 0; i < hist.length; i++) {
            ProvenanceRecord storage r = records[hist[i]];
            if (r.previousHash != prev) return false;
            bytes32 computed = keccak256(
                abi.encode(r.recordId, r.modelId, r.eventType, r.ipfsMetadata, r.timestamp, r.operator, r.previousHash)
            );
            if (computed != r.recordHash) return false;
            prev = r.recordHash;
        }
        return true;
    }
}

contracts/SignedZKProvenanceTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./ModelAccessControl.sol";
import "./Verifier.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface ISignedZKModelRegistry {
    function getModelOwner(uint256 _id) external view returns (address);
    function getModelStatus(uint256 _id) external view returns (uint8);
    function isModelStaked(uint256 _id) external view returns (bool);
}

/// @title SignedZKProvenanceTracker
/// @notice Every provenance append requires a proof and current registry-owner authorization.
/// @dev Relayers need no registrar role. Governance can block models but cannot append records.
contract SignedZKProvenanceTracker is EIP712 {
    using ECDSA for bytes32;

    struct Authorization {
        uint256 nonce;
        bytes32 expectedHead;
        uint256 deadline;
        bytes signature;
    }

    bytes32 public constant SUBMISSION_TYPEHASH = keccak256(
        "SignedZKSubmission(uint256 modelId,uint8 eventType,bytes32 metadataHash,uint256 nullifier,uint256 nonce,bytes32 expectedHead,uint256 deadline)"
    );
    mapping(address => mapping(uint256 => bool)) public nonceUsed;
    error UnauthorisedSigner();
    error NonceAlreadyUsed();
    error StaleHead();
    error AuthorizationExpired();
    event SubmissionAuthorised(uint256 indexed modelId, address indexed owner, uint256 nonce, bytes32 metadataHash);
    enum EventType {
        REGISTERED,
        ACTIVATED,
        UPDATED,
        DEPRECATED,
        REVOKED,
        VERSION_RELEASED,
        TRANSFERRED,
        STAKED,
        UNSTAKED,
        SLASHED,
        ZK_PROOF_VERIFIED
    }

    struct ProvenanceRecord {
        uint256 recordId;
        uint256 modelId;
        EventType eventType;
        string ipfsMetadata;
        uint256 timestamp;
        address operator;
        bytes32 previousHash;
        bytes32 recordHash;
    }

    uint256 internal constant SNARK_SCALAR_FIELD =
        21888242871839275222246405745257275088548364400416034343698204186575808495617;

    ModelAccessControl public immutable accessControl;
    ISignedZKModelRegistry public immutable registry;
    Groth16Verifier public immutable verifier;

    uint256 private _recordCounter;
    mapping(uint256 => ProvenanceRecord) public records;
    mapping(uint256 => uint256[]) public modelHistory;
    mapping(uint256 => bytes32) public modelChainHead;
    mapping(uint256 => bool) public modelBlacklist;
    mapping(uint256 => string) public blacklistReasons;
    mapping(uint256 => bool) public nullifierUsed;

    event RecordAdded(
        uint256 indexed recordId,
        uint256 indexed modelId,
        EventType indexed eventType,
        address operator
    );
    event ProofVerified(
        uint256 indexed modelId,
        address indexed operator,
        uint256 indexed nullifier,
        uint256 statementHash,
        uint256 timestamp
    );
    event ModelBlacklisted(uint256 indexed modelId, string reason, address by);
    event ModelUnblacklisted(uint256 indexed modelId, address by);

    error ModelIsBlacklisted();
    error NotAuthorized();
    error ModelNotRegistered();
    error InvalidProof();
    error InvalidModelSignal();
    error InvalidStatementHash();
    error NullifierAlreadyUsed();

    constructor(address _accessControl, address _registry, address _verifier) EIP712("SignedZKProvenance", "1") {
        require(_accessControl != address(0), "Tracker: access control required");
        require(_registry != address(0), "Tracker: registry required");
        require(_verifier != address(0), "Tracker: verifier required");
        accessControl = ModelAccessControl(_accessControl);
        registry = ISignedZKModelRegistry(_registry);
        verifier = Groth16Verifier(_verifier);
    }

    function addSignedVerifiedRecord(
        uint256 _modelId,
        EventType _eventType,
        string calldata _canonicalMetadata,
        uint[2] calldata _pA,
        uint[2][2] calldata _pB,
        uint[2] calldata _pC,
        uint[3] calldata _pubSignals,
        Authorization calldata authorization
    ) external notBlacklisted returns (uint256) {
        _checkModelStatus(_modelId);
        if (modelBlacklist[_modelId]) revert ModelIsBlacklisted();

        if (_pubSignals[1] != _modelId) revert InvalidModelSignal();

        uint256 statementHash = _statementHash(_canonicalMetadata);
        if (_pubSignals[2] != statementHash) revert InvalidStatementHash();

        uint256 nullifier = _pubSignals[0];
        if (nullifierUsed[nullifier]) revert NullifierAlreadyUsed();

        if (block.timestamp > authorization.deadline) revert AuthorizationExpired();
        if (authorization.expectedHead != modelChainHead[_modelId]) revert StaleHead();
        address owner = registry.getModelOwner(_modelId);
        if (accessControl.isBlacklisted(owner)) revert NotAuthorized();
        if (nonceUsed[owner][authorization.nonce]) revert NonceAlreadyUsed();
        bytes32 metadataHash = keccak256(bytes(_canonicalMetadata));
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(
            SUBMISSION_TYPEHASH, _modelId, uint8(_eventType), metadataHash, nullifier,
            authorization.nonce, authorization.expectedHead, authorization.deadline
        )));
        if (digest.recover(authorization.signature) != owner) revert UnauthorisedSigner();

        bool verified = verifier.verifyProof(_pA, _pB, _pC, _pubSignals);
        if (!verified) revert InvalidProof();

        nullifierUsed[nullifier] = true;
        nonceUsed[owner][authorization.nonce] = true;
        emit ProofVerified(_modelId, owner, nullifier, statementHash, block.timestamp);
        emit SubmissionAuthorised(_modelId, owner, authorization.nonce, metadataHash);

        return _appendRecord(_modelId, _eventType, owner, _canonicalMetadata);
    }

    function blacklistModel(uint256 _modelId, string calldata _reason) external onlyAdmin {
        require(_modelId > 0, "Tracker: invalid model id");
        modelBlacklist[_modelId] = true;
        blacklistReasons[_modelId] = _reason;
        // Administrative actions are separate events, not unsigned provenance records.
        emit ModelBlacklisted(_modelId, _reason, msg.sender);
    }

    function unblacklistModel(uint256 _modelId) external onlyAdmin {
        require(modelBlacklist[_modelId], "Tracker: not blacklisted");
        modelBlacklist[_modelId] = false;
        delete blacklistReasons[_modelId];
        emit ModelUnblacklisted(_modelId, msg.sender);
    }

    function getModelHistory(uint256 _modelId) external view returns (ProvenanceRecord[] memory) {
        uint256[] storage ids = modelHistory[_modelId];
        ProvenanceRecord[] memory result = new ProvenanceRecord[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = records[ids[i]];
        }
        return result;
    }

    function verifyChain(uint256 _modelId) external view returns (bool) {
        uint256[] storage ids = modelHistory[_modelId];
        if (ids.length == 0) return true;

        bytes32 prevRecordHash = bytes32(0);

        for (uint256 i = 0; i < ids.length; i++) {
            ProvenanceRecord storage record = records[ids[i]];

            if (record.previousHash != prevRecordHash) {
                return false;
            }

            bytes32 computed = keccak256(
                abi.encode(
                    record.recordId,
                    record.modelId,
                    record.eventType,
                    record.ipfsMetadata,
                    record.timestamp,
                    record.operator,
                    record.previousHash
                )
            );
            if (record.recordHash != computed) {
                return false;
            }

            prevRecordHash = record.recordHash;
        }

        return prevRecordHash == modelChainHead[_modelId];
    }

    function getModelsStatus(uint256[] calldata _modelIds)
        external
        view
        returns (uint8[] memory statuses, bool[] memory blacklisted)
    {
        statuses = new uint8[](_modelIds.length);
        blacklisted = new bool[](_modelIds.length);
        for (uint256 i = 0; i < _modelIds.length; i++) {
            statuses[i] = registry.getModelStatus(_modelIds[i]);
            blacklisted[i] = modelBlacklist[_modelIds[i]];
        }
    }

    function computeStatementHash(string calldata _canonicalMetadata) external pure returns (uint256) {
        return _statementHash(_canonicalMetadata);
    }

    function _appendRecord(
        uint256 _modelId,
        EventType _eventType,
        address _operator,
        string memory _ipfsMetadata
    ) internal returns (uint256) {
        uint256 recordId = ++_recordCounter;
        bytes32 prevHash = modelChainHead[_modelId];

        ProvenanceRecord memory record = ProvenanceRecord({
            recordId: recordId,
            modelId: _modelId,
            eventType: _eventType,
            ipfsMetadata: _ipfsMetadata,
            timestamp: block.timestamp,
            operator: _operator,
            previousHash: prevHash,
            recordHash: bytes32(0)
        });

        record.recordHash = keccak256(
            abi.encode(
                record.recordId,
                record.modelId,
                record.eventType,
                record.ipfsMetadata,
                record.timestamp,
                record.operator,
                record.previousHash
            )
        );

        records[recordId] = record;
        modelHistory[_modelId].push(recordId);
        modelChainHead[_modelId] = record.recordHash;

        emit RecordAdded(recordId, _modelId, _eventType, _operator);
        return recordId;
    }

    function _checkModelStatus(uint256 _modelId) internal view {
        if (registry.getModelOwner(_modelId) == address(0)) revert ModelNotRegistered();
        uint8 status = registry.getModelStatus(_modelId);
        require(status != 3, "Tracker: model is revoked");
    }

    function _statementHash(string memory _canonicalMetadata) internal pure returns (uint256) {
        return uint256(keccak256(bytes(_canonicalMetadata))) % SNARK_SCALAR_FIELD;
    }

    modifier notBlacklisted() {
        if (accessControl.isBlacklisted(msg.sender)) revert NotAuthorized();
        _;
    }

    modifier onlyAdmin() {
        if (!accessControl.hasRole(accessControl.ADMIN(), msg.sender)) revert NotAuthorized();
        _;
    }
}

contracts/UngatedProvenanceTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title UngatedProvenanceTracker
 * @notice Identical-layout ungated CONTROL for isolating admission-gate cost.
 *
 *  This is NOT the passive-anchoring baseline of Section 6.2. It is a
 *  microbenchmark control: the record struct, canonical-metadata handling,
 *  hash-linked chaining and _appendRecord logic are byte-identical to the
 *  gated trackers, and the ONLY difference is that no admission check is
 *  performed. The difference in gasUsed is therefore attributable to the
 *  gate rather than to storage layout or payload.
 */
contract UngatedProvenanceTracker {
    // Keep numeric event codes aligned with ZKProvenanceTracker so the
    // three-way experiment uses the same lifecycle state progression.
    enum EventType {
        REGISTERED,
        ACTIVATED,
        UPDATED,
        DEPRECATED,
        REVOKED,
        VERSION_RELEASED,
        TRANSFERRED,
        STAKED,
        UNSTAKED,
        SLASHED,
        ZK_PROOF_VERIFIED
    }

    struct ProvenanceRecord {
        uint256 recordId;
        uint256 modelId;
        EventType eventType;
        string ipfsMetadata;
        uint256 timestamp;
        address operator;
        bytes32 previousHash;
        bytes32 recordHash;
    }

    uint256 internal constant SNARK_SCALAR_FIELD =
        21888242871839275222246405745257275088548364400416034343698204186575808495617;

    uint256 private _recordCounter;

    mapping(uint256 => ProvenanceRecord) public records;
    mapping(uint256 => uint256[]) public modelHistory;
    mapping(uint256 => bytes32) public modelChainHead;

    event RecordAdded(uint256 indexed recordId, uint256 indexed modelId, EventType eventType, address indexed operator);

    /// @notice Ungated write: no signature, no proof, no nullifier, no owner binding.
    function addRecord(
        uint256 _modelId,
        EventType _eventType,
        string calldata _canonicalMetadata,
        address _assertedOwner
    ) external returns (uint256) {
        return _appendRecord(_modelId, _eventType, _assertedOwner, _canonicalMetadata);
    }


    function _appendRecord(
        uint256 _modelId,
        EventType _eventType,
        address _operator,
        string memory _ipfsMetadata
    ) internal returns (uint256) {
        uint256 recordId = ++_recordCounter;
        bytes32 prevHash = modelChainHead[_modelId];

        ProvenanceRecord memory record = ProvenanceRecord({
            recordId: recordId,
            modelId: _modelId,
            eventType: _eventType,
            ipfsMetadata: _ipfsMetadata,
            timestamp: block.timestamp,
            operator: _operator,
            previousHash: prevHash,
            recordHash: bytes32(0)
        });

        record.recordHash = keccak256(
            abi.encode(
                record.recordId, record.modelId, record.eventType, record.ipfsMetadata,
                record.timestamp, record.operator, record.previousHash
            )
        );

        records[recordId] = record;
        modelHistory[_modelId].push(recordId);
        modelChainHead[_modelId] = record.recordHash;

        emit RecordAdded(recordId, _modelId, _eventType, _operator);
        return recordId;
    }

    function _statementHash(string memory _canonicalMetadata) internal pure returns (uint256) {
        return uint256(keccak256(bytes(_canonicalMetadata))) % SNARK_SCALAR_FIELD;
    }

    function statementHashOf(string calldata _canonicalMetadata) external pure returns (uint256) {
        return _statementHash(_canonicalMetadata);
    }

    function getHistoryLength(uint256 _modelId) external view returns (uint256) {
        return modelHistory[_modelId].length;
    }

    function verifyChain(uint256 _modelId) external view returns (bool) {
        uint256[] storage hist = modelHistory[_modelId];
        bytes32 prev = bytes32(0);
        for (uint256 i = 0; i < hist.length; i++) {
            ProvenanceRecord storage r = records[hist[i]];
            if (r.previousHash != prev) return false;
            bytes32 computed = keccak256(
                abi.encode(r.recordId, r.modelId, r.eventType, r.ipfsMetadata, r.timestamp, r.operator, r.previousHash)
            );
            if (computed != r.recordHash) return false;
            prev = r.recordHash;
        }
        return true;
    }
}

contracts/PassiveAnchoringTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title PassiveAnchoringTracker
/// @notice Minimal passive-anchoring baseline: writes the submitted provenance
///         payload directly into a per-model array. It performs NO statement-hash
///         recomputation, NO proof verification, NO nullifier check, and NO owner
///         binding. The ledger is used purely as an append-only store.
contract PassiveAnchoringTracker {
    struct AnchoredRecord {
        uint256 modelId;
        string modelHash;
        string artifactCid;
        string canonicalMetadata;
        address assertedOwner;
        uint256 timestamp;
    }

    uint256 private _recordCounter;
    mapping(uint256 => AnchoredRecord[]) public modelRecords;

    event RecordAnchored(uint256 indexed recordId, uint256 indexed modelId, address assertedOwner);

    function anchorRecord(
        uint256 _modelId,
        string calldata _modelHash,
        string calldata _artifactCid,
        string calldata _canonicalMetadata,
        address _assertedOwner
    ) external returns (uint256) {
        uint256 recordId = ++_recordCounter;

        modelRecords[_modelId].push(
            AnchoredRecord({
                modelId: _modelId,
                modelHash: _modelHash,
                artifactCid: _artifactCid,
                canonicalMetadata: _canonicalMetadata,
                assertedOwner: _assertedOwner,
                timestamp: block.timestamp
            })
        );

        emit RecordAnchored(recordId, _modelId, _assertedOwner);
        return recordId;
    }

    function getRecordCount(uint256 _modelId) external view returns (uint256) {
        return modelRecords[_modelId].length;
    }
}

